								</v-col>
								<v-col cols="12" md="3" class="">
									<v-text-field v-if="!localData.metaData.useDefaultCommission" class="left-input" v-model="localData.metaData.agentFactorCommission" type="number" label="درصد کارمزد" :error-messages="errorMessages" :rules="[(val) => val >= 0 && val < 100 || 'درصد کارمزد صحیح نمی باشد']" />
								</v-col>
								<v-col cols="12" md="3" class="">
									<v-text-money class="left-input" v-if="!localData.metaData.useDefaultCommission" v-model="localData.metaData.maxAgentFactorCommission" label="حداکثر مبلغ کارمزد (به تومان)" :error-messages="errorMessages" :rules="[(val) => localData.metaData.maxAgentFactorCommission >= 0 || 'مبلغ حداکثر کارمزد صحیح نمی باشد']" />
								</v-col>
							</v-row>
